import{_ as a,o as t,c as e,a2 as r}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 11 章 文件与目录：整理、搜索、批量处理（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第11章 文件与目录：整理、搜索、批量处理（易懂版）.md","filePath":"easy/第11章 文件与目录：整理、搜索、批量处理（易懂版）.md"}'),l={name:"easy/第11章 文件与目录：整理、搜索、批量处理（易懂版）.md"};function s(n,o,i,d,c,h){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="第-11-章-文件与目录-整理、搜索、批量处理-易懂版" tabindex="-1">第 11 章 文件与目录：整理、搜索、批量处理（易懂版） <a class="header-anchor" href="#第-11-章-文件与目录-整理、搜索、批量处理-易懂版" aria-label="Permalink to &quot;第 11 章 文件与目录：整理、搜索、批量处理（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 11 章 文件与目录：整理、搜索、批量处理（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 11 章 文件与目录：整理、搜索、批量处理.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>找文件、理文件、批量改文件——我的看家本领，解放你的文件夹。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>你的电脑就像一间堆满东西的仓库。我不是只给你指路的人，而是<strong>帮你搬货、贴标签、重新上架的仓管员</strong>——你说&quot;把工具放一块、资料放一块&quot;，我就动手。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>按规则整理</strong>：告诉我分类规则（按类型？按日期？按项目？），我批量移动/重命名/归档。</li><li><strong>按条件搜索</strong>：找&quot;含某句话的文件&quot;&quot;上个月改过的文件&quot;&quot;超过 100MB 的文件&quot;——一句话的事。</li><li><strong>批量处理</strong>：给几十个文件统一改名、转格式、加水印——手工会疯，我几分钟干完。</li></ol><h2 id="整理三原则-先想清楚再动手" tabindex="-1">整理三原则（先想清楚再动手） <a class="header-anchor" href="#整理三原则-先想清楚再动手" aria-label="Permalink to &quot;整理三原则（先想清楚再动手）&quot;">​</a></h2><ol><li><strong>先备份再批量</strong>：大动作前先复制一份，出错了能退；</li><li><strong>规则先给你看</strong>：我会先说我打算怎么分，你点头我再动；</li><li><strong>命名要能看懂</strong>：<code>2026-08-01-周报.md</code> 比 <code>1.docx</code> 好找一百倍。</li></ol><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;把 <code>下载</code> 文件夹里所有图片按月份分到 <code>图片/2026-08</code> 这种文件夹里，重复的标上副本。&quot;</p><p><strong>你会看到</strong>：我先列整理方案 → 你确认 → 我批量移动 → 给你一份&quot;改了什么&quot;清单。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 不说规则就让整理——<strong>乱分比不分还糟</strong>；</li><li>❌ 批量删除不备份——<strong>删之前一定留后路</strong>；</li><li>❌ 整理完不检查——<strong>抽样看看，确认没放错</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>整理文件 = 先备份 + 说规则 + 我执行 + 你抽查。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>看一眼你电脑里最乱的文件夹——<strong>30 秒想一条整理规则</strong>，然后对我说：&quot;按……规则整理一下。&quot;</p><p>👉 [下一章：数据与表格，清洗、分析与图表（易懂版）](第12章 数据与表格：清洗、分析与图表（易懂版）.md)</p>',19)])])}const q=a(l,[["render",s]]);export{u as __pageData,q as default};
